import csv
from collections import defaultdict
f = list(csv.reader(open("ae_ci_age_gender.csv")))
hdr=[h.strip().lower() for h in f[0]]
print("HDR:",hdr)
def find(n):
    for i,h in enumerate(hdr):
        if n in h: return i
    return None
iy=find("year"); ia=find("age"); ig=find("gender"); ia_=find("actual"); ie_=find("expected")
print("idx year/age/gender/act/exp:",iy,ia,ig,ia_,ie_)
if iy is None or ia is None or ia_ is None or ie_ is None:
    for r in f[1:8]: print(r)
else:
    age_y=defaultdict(lambda:[0.0,0.0]); y=defaultdict(lambda:[0.0,0.0]); bad=0
    for r in f[1:]:
        if len(r)<=max(ia_,ie_): continue
        try:
            a=float(r[ia_].replace(",","")); e=float(r[ie_].replace(",",""))
        except Exception:
            bad+=1; continue
        age_y[(r[ia],r[iy])][0]+=a; age_y[(r[ia],r[iy])][1]+=e
        y[r[iy]][0]+=a; y[r[iy]][1]+=e
    print("bad rows:",bad)
    print("yearly (aggregated over age/gender):")
    for k in sorted(y):
        print(k, round(y[k][0]/y[k][1],3), "exp=", int(y[k][1]))
    years=sorted(y)
    print("age x year A/E (exp):")
    for a in sorted(set(k[0] for k in age_y)):
        cells=[]
        for yr in years:
            if (a,yr) in age_y:
                t=age_y[(a,yr)]
                cells.append(f"{yr}:{t[0]/t[1]:.2f}({int(t[1])})")
        print(a, " ".join(cells))
